<script setup lang="ts">
import { inject, onBeforeUnmount, onMounted, ref, watch, type Ref } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { addDays, command, displayTime, errorMessage, request, today } from '@worktime/api-client';
import CalendarView from './CalendarView.vue';
interface Rule {code:string;label:string;enabled:boolean;time:string;dayType:string;dayOfWeek:number;dayOfMonth:number;threshold:number;recipients:string;template:string}
interface Snapshot {id:string;effectiveFrom:string;params:Record<string,string|number>;rules:Rule[]}
interface Config {current:Snapshot;latestVersion:string;history:Snapshot[]}
interface Job {id:string;type:string;businessKey:string;status:string;plannedAt:string;nextRunAt:string;attempts:number;error:string|null;completedAt:string|null}
interface Notification {id:string;recipient:string;eventType:string;body:string;status:string;error:string|null;createdAt:string}
interface Audit {id:string;actorType:string;actorName:string;jobId:string|null;action:string;objectType:string;objectId:string;beforeData:unknown;afterData:unknown;reason:string;createdAt:string}
interface Health {worker:{workerKey:string;heartbeatAt:string;lastScanDate:string}[];pendingJobs:number;failedJobs:number;pendingNotifications:number}
const tab=ref('config'),busy=ref(false),error=ref(''),notice=ref(''),config=ref<Config>(),draft=ref<Snapshot>(),effectiveFrom=ref(addDays(today(),1)),reason=ref(''),preview=ref<{effectiveFrom:string;existingFutureDays:number;notes:string[]}>(),jobs=ref<Job[]>([]),notifications=ref<Notification[]>([]),audits=ref<Audit[]>([]),health=ref<Health>(),objectType=ref(''),objectId=ref('');
const sharedBusy=inject<Ref<boolean>>('operationBusy');watch(busy,v=>{if(sharedBusy)sharedBusy.value=v;});
const recipientChoices=(rule:Rule)=>{const allowed=rule.code==='MONTH_CLOSE'?['ADMIN']:rule.code.startsWith('APPROVAL_')?['APPROVER','APPROVER_SUPERVISOR','ADMIN']:['SELF','SELF_MANAGER','ADMIN'];return [{id:'SELF',name:'本人'},{id:'SELF_MANAGER',name:'本人及直属负责人'},{id:'APPROVER',name:'审批人'},{id:'APPROVER_SUPERVISOR',name:'审批人上级'},{id:'ADMIN',name:'管理员'}].filter(o=>allowed.includes(o.id));};
const fields=[{key:'dayLimitMinutes',name:'每天工时上限（分钟）',min:480,max:1440},{key:'redFlagMinutes',name:'超长说明阈值（分钟）',min:480,max:1440},{key:'defaultDayMinutes',name:'默认工作日基数（分钟）',min:0,max:480},{key:'stepMinutes',name:'填报步长（分钟）',min:15,max:60},{key:'submitWeekday',name:'周提交截止星期',min:1,max:7},{key:'submitTime',name:'周提交截止时刻',type:'time'},{key:'approveWeekday',name:'审批截止星期',min:1,max:7},{key:'approveTime',name:'审批截止时刻',type:'time'},{key:'closeDay',name:'每月封账日',min:1,max:28},{key:'dailyCompletionTime',name:'填报及时性判断时刻',type:'time'}];
const state:Record<string,string>={PENDING:'待执行',RUNNING:'执行中',RETRY:'待重试',FAILED:'失败',COMPLETED:'已完成',LOCAL:'本地收件箱',SENT:'已发送',QUEUED:'待发送',USER:'用户',SYSTEM:'系统'};
async function load(){busy.value=true;error.value='';try{if(tab.value==='config'){config.value=await request<Config>('/operations/config');draft.value=JSON.parse(JSON.stringify(config.value.current));effectiveFrom.value=addDays([today(),...config.value.history.map(s=>s.effectiveFrom)].sort().at(-1)!,1);preview.value=undefined;}if(tab.value==='jobs'){[jobs.value,health.value]=await Promise.all([request<Job[]>('/operations/jobs'),request<Health>('/operations/health')]);}if(tab.value==='notifications')notifications.value=await request<Notification[]>('/operations/notifications');if(tab.value==='audit')audits.value=await request<Audit[]>(`/operations/audit?${new URLSearchParams(Object.entries({objectType:objectType.value,objectId:objectId.value}).filter(([,v])=>v))}`);}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function changeTab(v:string){if(busy.value||sharedBusy?.value)return;tab.value=v;if(v!=='calendar')await load();}
function body(){return {expectedVersion:config.value!.latestVersion,effectiveFrom:effectiveFrom.value,params:Object.fromEntries(Object.entries(draft.value!.params).map(([key,value])=>[key,key.endsWith('Time')?value:Number(value)])),rules:draft.value!.rules,reason:reason.value};}
async function inspect(){busy.value=true;error.value='';try{preview.value=await command('/operations/config/preview',body());}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function save(){if(!preview.value)return;busy.value=true;error.value='';try{await request('/operations/config',{method:'PUT',body:JSON.stringify(body())});notice.value='已创建新的生效版本，历史版本保留。';reason.value='';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function retry(kind:string,id:string){busy.value=true;error.value='';try{await command(`/operations/${kind}/${id}/retry`);notice.value='已重新入队，执行结果请刷新查看。';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
watch([draft,effectiveFrom,reason],()=>{preview.value=undefined;},{deep:true});onMounted(load);onBeforeRouteLeave(()=>!busy.value&&(!reason.value||window.confirm('参数说明尚未提交，确定离开？')));onBeforeUnmount(()=>{if(sharedBusy)sharedBusy.value=false;});
</script>
<template><div class="workflow-page"><div class="workflow-head"><div><h1>规则与运行管理</h1><p>统一维护生效规则，核对自动任务与消息实际执行情况。</p></div><button v-if="tab!=='calendar'" :disabled="busy" @click="load">刷新</button></div><nav class="workflow-tabs"><button v-for="t in [{id:'config',name:'业务参数'},{id:'calendar',name:'工作日历'},{id:'jobs',name:'自动任务'},{id:'notifications',name:'通知投递'},{id:'audit',name:'操作审计'}]" :key="t.id" :class="{active:tab===t.id}" :disabled="busy||sharedBusy" @click="changeTab(t.id)">{{ t.name }}</button></nav><p v-if="error" class="workflow-error" role="alert">{{ error }}</p><p v-if="notice" class="workflow-success">{{ notice }}</p><CalendarView v-if="tab==='calendar'" /><template v-if="tab==='config'&&draft&&config"><p class="workflow-note">当前生效日 {{ config.current.effectiveFrom }} · 最新版本 {{ config.latestVersion }}。日历显式维护值优先，已产生的月门禁、送审截止与正式月报保留。</p><form @submit.prevent="inspect"><section class="workflow-panel"><h2>填报与截止规则</h2><div class="settings-grid"><label v-for="f in fields" :key="f.key">{{ f.name }}<input v-model="draft.params[f.key]" :type="f.type||'number'" :min="f.min" :max="f.max" required :disabled="busy" /></label></div><p class="workflow-note">星期一为 1，星期日为 7。自动送审与封账的执行时间由上述截止参数控制。</p></section><section class="workflow-panel"><h2>内置提醒与自动动作</h2><details v-for="rule in draft.rules" :key="rule.code"><summary>{{ rule.label }} · {{ rule.enabled?'开启':'停用' }}</summary><div class="settings-grid"><label><span>启用规则</span><input v-model="rule.enabled" type="checkbox" :disabled="busy" /></label><label>时刻<span v-if="rule.code==='AUTO_SUBMIT'">由周提交截止控制：{{ draft.params.submitTime }}</span><span v-else-if="rule.code==='MONTH_CLOSE'">每月 {{ draft.params.closeDay }} 日 00:00</span><input v-else v-model="rule.time" type="time" :disabled="busy" /></label><label>周期<select aria-label="周期" v-model="rule.dayType" :disabled="busy||['AUTO_SUBMIT','MONTH_CLOSE','REJECTED'].includes(rule.code)"><option value="WORKDAY">工作日</option><option value="DAILY">每日</option><option value="WEEKLY">每周</option><option value="MONTHLY">每月</option><option v-if="rule.code==='REJECTED'" value="EVENT">事件触发</option></select></label><label v-if="rule.dayType==='WEEKLY'">星期<input v-model.number="rule.dayOfWeek" type="number" min="1" max="7" :disabled="busy" /></label><label v-if="rule.dayType==='MONTHLY'">日期<input v-model.number="rule.dayOfMonth" type="number" min="1" max="28" :disabled="busy" /></label><label>累计阈值<input v-model.number="rule.threshold" type="number" min="1" max="90" :disabled="busy" /></label><label>接收人<select aria-label="接收人" v-model="rule.recipients" :disabled="busy"><option v-for="o in recipientChoices(rule)" :key="o.id" :value="o.id">{{ o.name }}</option></select></label></div><label class="rule-template">通知文案<textarea v-model="rule.template" rows="2" maxlength="1000" :disabled="busy" /></label><small>可用占位符：{date}、{name}、{week}、{count}</small></details></section><section class="workflow-panel"><div class="settings-grid"><label>新版本生效日期<input v-model="effectiveFrom" type="date" :min="addDays(today(),1)" required :disabled="busy" /></label><label>变更理由<input v-model="reason" required maxlength="500" :disabled="busy" /></label></div><div v-if="preview" class="workflow-warning"><p>将于 {{ preview.effectiveFrom }} 生效，已有未来人日 {{ preview.existingFutureDays }} 条。</p><p v-for="line in preview.notes" :key="line">{{ line }}</p></div><div class="workflow-actions"><button :disabled="busy" type="submit">预览生效影响</button><button class="primary" type="button" :disabled="busy||!preview" @click="save">确认创建规则版本</button></div></section></form><details><summary>历史配置版本 {{ config.history.length }} 个</summary><article v-for="item in config.history" :key="item.id" class="workflow-panel"><strong>{{ item.effectiveFrom }} · 版本 {{ item.id }}</strong><p v-for="f in fields" :key="f.key">{{ f.name }}：{{ item.params[f.key] }}</p></article></details></template><template v-if="tab==='jobs'"><section v-if="health" class="workflow-panel"><h2>运行状态</h2><p>待执行 {{ health.pendingJobs }} · 失败 {{ health.failedJobs }} · 待投递 {{ health.pendingNotifications }}</p><p v-for="w in health.worker" :key="w.workerKey">工作进程 {{ w.workerKey }} · 心跳 {{ displayTime(w.heartbeatAt) }} · 扫描至 {{ w.lastScanDate }}</p><p v-if="!health.worker.length" class="workflow-warning">暂无工作进程心跳，请检查调度服务。</p></section><section class="workflow-panel"><div v-if="!jobs.length" class="workflow-empty">暂无任务记录。</div><div class="workflow-table-wrap"><table v-if="jobs.length" class="workflow-table"><thead><tr><th>任务</th><th>状态</th><th>计划 / 下次执行</th><th>尝试次数</th><th>异常</th><th>操作</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{ job.type }}<small>{{ job.businessKey }}</small></td><td>{{ state[job.status]??job.status }}</td><td>{{ displayTime(job.plannedAt) }}<small>{{ displayTime(job.nextRunAt) }}</small></td><td>{{ job.attempts }}</td><td>{{ job.error||'无' }}</td><td><button v-if="job.status==='FAILED'" :disabled="busy" @click="retry('jobs',job.id)">重新入队</button></td></tr></tbody></table></div></section></template><template v-if="tab==='notifications'"><p class="workflow-note">“本地收件箱”代表本地验证记录，未发送到企业微信。正式渠道以实际投递结果为准。</p><div v-if="!notifications.length" class="workflow-empty">暂无通知记录。</div><article v-for="n in notifications" :key="n.id" class="workflow-panel"><div class="workflow-between"><strong>{{ n.recipient }} · {{ n.eventType }}</strong><span>{{ state[n.status]??n.status }}</span></div><p class="preserve-lines">{{ n.body }}</p><p>{{ displayTime(n.createdAt) }}</p><p v-if="n.error" class="workflow-error">{{ n.error }}</p><button v-if="n.status==='FAILED'" :disabled="busy" @click="retry('notifications',n.id)">重试投递</button></article></template><template v-if="tab==='audit'"><form class="workflow-filters" @submit.prevent="load"><label>对象类型<input v-model="objectType" placeholder="可留空" :disabled="busy" /></label><label>对象 ID<input v-model="objectId" placeholder="可留空" :disabled="busy" /></label><button :disabled="busy">筛选最近 100 条</button></form><p v-if="!audits.length" class="workflow-empty">当前筛选无审计记录。</p><article v-for="item in audits" :key="item.id" class="workflow-panel"><div class="workflow-between"><strong>{{ item.actorName||state[item.actorType] }} · {{ item.action }}</strong><small>{{ displayTime(item.createdAt) }}</small></div><p>{{ item.objectType }} / {{ item.objectId }}{{ item.jobId?` · 自动任务 ${item.jobId}`:'' }}</p><p>{{ item.reason }}</p><details><summary>查看变更前后内容</summary><p>变更前</p><pre>{{ typeof item.beforeData==='string'?item.beforeData:JSON.stringify(item.beforeData,null,2) }}</pre><p>变更后</p><pre>{{ typeof item.afterData==='string'?item.afterData:JSON.stringify(item.afterData,null,2) }}</pre></details></article></template></div></template>
<style scoped>
.settings-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--ts-space-20); margin-top: var(--ts-space-20); }
.settings-grid label, .rule-template { display: grid; min-width: 0; gap: var(--ts-space-8); color: var(--ts-color-text-secondary); font-size: var(--ts-type-label); }
.rule-template { margin: var(--ts-space-16) 0; }
.workflow-table small { display: block; margin-top: var(--ts-space-4); color: var(--ts-color-text-muted); }
@media (max-width: 800px) { .settings-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 550px) { .settings-grid { grid-template-columns: 1fr; gap: var(--ts-space-16); } }
</style>
